/**
 * Debug helper for visualizing Gaussian Splat bounding boxes.
 *
 * Helps debug splat placement by showing:
 * - Overall bounding box of the entire model
 * - Per-instance oriented 3D wireframe boxes showing individual splat extents
 *
 * For point cloud visualization, use GaussianSplatsPoints instead.
 *
 * @class GaussianSplatsHelper
 * @extends THREE.Object3D
 * @short Visualizes model bounding box and per-instance wireframe boxes.
 * @category Helpers
 * @tags WebGPU
 */
export class GaussianSplatsHelper {
    static get type(): string;
    /**
     * Create a GaussianSplatsHelper.
     *
     * @param {GaussianSplats} splats The GaussianSplats instance to visualize.
     * @param {Object} [options={}] Options.
     * @param {boolean} [options.showBoundingBox=true] Enable overall model bounding box visualization.
     * @param {boolean} [options.showPerInstanceBoundingBoxes=false] Enable per-splat oriented 3D wireframe box visualization.
     * @param {number} [options.boxColor=0x00ff00] Overall bounding box wireframe color.
     * @param {number} [options.boxOpacity=0.8] Overall bounding box line opacity.
     * @param {number} [options.perInstanceBoxColor=0xff0000] Per-instance wireframe box color.
     */
    constructor(splats: GaussianSplats, options?: {
        showBoundingBox?: boolean;
        showPerInstanceBoundingBoxes?: boolean;
        boxColor?: number;
        boxOpacity?: number;
        perInstanceBoxColor?: number;
    });
    isGaussianSplatsHelper: boolean;
    _splats: GaussianSplats;
    _showBoundingBox: boolean;
    _showPerInstanceBoundingBoxes: boolean;
    _boxColor: any;
    _boxOpacity: number;
    _perInstanceBoxColor: any;
    _boundingBox: any;
    _perInstanceBoxes: any;
    /**
     * Create the overall model bounding box visualization.
     * @private
     */
    private _createBoundingBox;
    /**
     * Compute bounding box vertices from min/max bounds.
     * @private
     */
    private _computeBoundingBoxVertices;
    /**
     * Create the per-instance oriented 2D wireframe plane visualization.
     * Uses 2D planes oriented by splat rotation, since Gaussian splats are 2D ellipses.
     * @private
     */
    private _createPerInstanceBoxes;
    /**
     * Compute transformed 2D plane vertices for all splats.
     * Uses 2D planes scaled by X and Y dimensions (splats are 2D ellipses).
     * @private
     */
    private _computePerInstancePlaneVertices;
    /**
     * Extract array from various buffer formats.
     * @private
     */
    private _getBufferArray;
    /**
     * Extract positions from packed positionsScales buffer.
     * Layout: [pos0.xyz, scale0.xyz, pos1.xyz, scale1.xyz, ...]
     * 6 floats per splat (2 contiguous vec3).
     * @private
     */
    private _getPositions;
    /**
     * Extract scales from packed positionsScales buffer.
     * Layout: [pos0.xyz, scale0.xyz, pos1.xyz, scale1.xyz, ...]
     * 6 floats per splat (2 contiguous vec3).
     * @private
     */
    private _getScales;
    /**
     * Extract rotations from packed rotationsColors buffer.
     * Layout: [rot0.xyzw, color0.rgba, rot1.xyzw, color1.rgba, ...]
     * @private
     */
    private _getRotations;
    /**
     * Update visualizations when splat data changes.
     */
    update(): void;
    /**
     * Dispose of helper resources.
     */
    dispose(): void;
}
